#teste1 C_mu == S_mu == mu
def teste1(Y, var):
    n = len(Y)
    mu = np.mean(Y)

    ell0 = (
    - (n / 2) * np.log(2 * np.pi)
    - (n / 2) * np.log(var)
    - (1 / (2 * var)) * np.sum((Y - mu)**2)
    )

    L0 = np.exp(ell0)

    print("Mu: ", mu)
    print("Ell0: ", ell0)
    print("L0: ", L0)

    return ell0

print("Teste 1:")
ll0 = teste1(Yt, var2)

#-----------------------------------------------------------------------------------------------------------------------

#teste 2 C_mu != S_mu
def teste2(Yc, Ys, var):
    n = len(Yc) + len(Ys)
    C_mu = np.mean(Yc)
    S_mu = np.mean(Ys)

    ell1 = (
    - (n / 2) * np.log(2 * np.pi)
    - (n / 2) * np.log(var)
    - (1 / (2 * var)) *
      (np.sum((Yc - C_mu)**2) + np.sum((Ys - S_mu)**2))
    )

    L1 = np.exp(ell1)

    print("C_mu: ", C_mu)
    print("S_mu: ", S_mu)
    print("Ell0: ", ell1)
    print("L0: ", L1)

    return ell1

print("Teste 2:")
ll1 = teste2(YC, YS, var2)

