#Questao 4 -> Using alpha = 0.05

def Wobs(Yc, Ys, var):
    nC = len(Yc)
    nS = len(Ys)

    w = (1 / var) * (nC * nS / (nC + nS)) * (np.mean(Yc) - np.mean(Ys))**2

    return w

print("Wobs = ", Wobs(YC, YS, var2))
